namespace Harborline.Kernel.Core;

public static class KernelRecoveryErrors
{
    public const string CapabilityRequired = "kernel.configuration-recovery-capability-required";
    public const string ReasonRequired = "kernel.recovery-reason-required";
    public const string AuthoritySnapshotRequired = "kernel.recovery-authority-snapshot-required";
    public const string TenantMismatch = "kernel.recovery-tenant-mismatch";
    public const string EffectiveGenerationMissing = "kernel.effective-generation-missing";
    public const string EffectiveGenerationCorrupt = "kernel.effective-generation-corrupt";
    public const string EffectivePointerUnbound = "kernel.effective-pointer-unbound";
}

/// <summary>
/// The kernel profile record: the capabilities the kernel declares with its own implementation,
/// before and without any catalogue or released definition.
/// </summary>
public static class KernelProfile
{
    public const string ConfigurationRecovery = "configuration-recovery";

    public static IReadOnlyCollection<string> Capabilities { get; } = [ConfigurationRecovery];
}

/// <summary>Point-of-use admission of the constrained configuration-recovery capability.</summary>
public interface IKernelConfigurationRecoveryCapability
{
    ValueTask<bool> CanRecoverAsync(string actorId, string tenantKey, CancellationToken cancellationToken = default);
}

/// <summary>A prepared generation a crash left behind. Recovery never activates it.</summary>
public sealed record PreparedGenerationResidue(string CandidateDigest, string ProjectionKey);

/// <summary>The effective pointer and the evidence intent its commit was bound to.</summary>
public sealed record EffectivePointer(string Digest, string? EvidenceIntentId);

/// <summary>One committed evidence intent and whether the outbox has published it.</summary>
public sealed record EvidenceOutboxEntry(string EvidenceIntentId, bool Published);

/// <summary>What the host's kernel profile store holds for one tenant. No catalogue read is part of it.</summary>
public sealed record KernelProfileSnapshot(
    string TenantKey,
    EffectivePointer? EffectivePointer,
    ReadOnlyMemory<byte>? EffectiveContent,
    PreparedGenerationResidue? Prepared,
    IReadOnlyList<EvidenceOutboxEntry> Outbox);

public interface IKernelProfileReader
{
    ValueTask<KernelProfileSnapshot?> ReadAsync(string tenantKey, CancellationToken cancellationToken = default);
}

public sealed record ConfigurationRecoveryRequest(
    string RecoveryId,
    string TenantKey,
    string ActorId,
    string Reason,
    string AuthoritySnapshot);

public enum ConfigurationResidue { PreparedGeneration, EffectivePointer, EvidenceOutbox }

public enum ConfigurationTerminalState { Abandoned, Confirmed, Published }

public sealed record ConfigurationRepair(ConfigurationResidue Residue, string Identity, ConfigurationTerminalState Terminal);

/// <summary>The one record a recovery commits: each residue's terminal state, with the reason and authority snapshot behind it.</summary>
public sealed record ConfigurationRecoveryRecord(
    string RecoveryId,
    string TenantKey,
    string EffectiveDigest,
    IReadOnlyList<ConfigurationRepair> Repairs,
    string Reason,
    string AuthoritySnapshot);

/// <summary>Why no write happened; State names the profile state the operator must resolve.</summary>
public sealed record ConfigurationRecoveryRefusal(string Code, string State);

public sealed record ConfigurationRecoveryResult<TResult>(
    ConfigurationRecoveryRecord? Record,
    TResult? Value,
    ConfigurationRecoveryRefusal? Refusal)
{
    public bool Committed => Refusal is null;
}

/// <summary>
/// Brings a prepared generation, the effective pointer and the evidence outbox left by a crash to a
/// terminal state, or refuses before any write naming the state. Reads the kernel profile only; it
/// holds no seam to a catalogue, a pack or a released definition, so authority is never established
/// through one. The pointer is never moved: an earlier generation becomes effective only through a
/// new evidenced activation.
/// </summary>
public sealed class ConfigurationRecovery
{
    private static readonly JsonSerializerOptions AuditJson = new(JsonSerializerDefaults.Web);
    private readonly IKernelProfileReader _profile;
    private readonly IKernelConfigurationRecoveryCapability? _capability;
    private readonly KernelClock _clock;

    public ConfigurationRecovery(IKernelProfileReader profile, IKernelConfigurationRecoveryCapability? capability, KernelClock clock)
    {
        _profile = profile ?? throw new ArgumentNullException(nameof(profile));
        _capability = capability;
        _clock = clock ?? throw new ArgumentNullException(nameof(clock));
    }

    public async ValueTask<ConfigurationRecoveryResult<TResult>> RecoverAsync<TResult>(
        ConfigurationRecoveryRequest request,
        IKernelTransactionPort<ConfigurationRecoveryRecord, TResult> port,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        ArgumentNullException.ThrowIfNull(port);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.RecoveryId);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.TenantKey);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.ActorId);
        static ConfigurationRecoveryResult<TResult> Refuse(string code, string state) => new(null, default, new(code, state));

        if (string.IsNullOrWhiteSpace(request.Reason)) return Refuse(KernelRecoveryErrors.ReasonRequired, "reason-absent");
        if (string.IsNullOrWhiteSpace(request.AuthoritySnapshot))
            return Refuse(KernelRecoveryErrors.AuthoritySnapshotRequired, "authority-snapshot-absent");
        if (_capability is null
            || !await _capability.CanRecoverAsync(request.ActorId, request.TenantKey, cancellationToken).ConfigureAwait(false))
            return Refuse(KernelRecoveryErrors.CapabilityRequired, KernelProfile.ConfigurationRecovery);

        var profile = await _profile.ReadAsync(request.TenantKey, cancellationToken).ConfigureAwait(false);
        if (profile is null) return Refuse(KernelRecoveryErrors.EffectiveGenerationMissing, "profile-absent");
        if (!string.Equals(profile.TenantKey, request.TenantKey, StringComparison.Ordinal))
            return Refuse(KernelRecoveryErrors.TenantMismatch, "profile-tenant-differs");
        if (profile.EffectivePointer is null || string.IsNullOrWhiteSpace(profile.EffectivePointer.Digest))
            return Refuse(KernelRecoveryErrors.EffectiveGenerationMissing, "pointer-missing");
        if (profile.EffectiveContent is not { } content)
            return Refuse(KernelRecoveryErrors.EffectiveGenerationMissing, "content-missing");
        if (!string.Equals(Convert.ToHexStringLower(SHA256.HashData(content.Span)), profile.EffectivePointer.Digest, StringComparison.Ordinal))
            return Refuse(KernelRecoveryErrors.EffectiveGenerationCorrupt, "content-digest-mismatch");
        if (string.IsNullOrWhiteSpace(profile.EffectivePointer.EvidenceIntentId))
            return Refuse(KernelRecoveryErrors.EffectivePointerUnbound, "pointer-without-evidence-intent");

        var repairs = new List<ConfigurationRepair>();
        if (profile.Prepared is not null)
            repairs.Add(new(ConfigurationResidue.PreparedGeneration, profile.Prepared.CandidateDigest, ConfigurationTerminalState.Abandoned));
        repairs.Add(new(ConfigurationResidue.EffectivePointer, profile.EffectivePointer.Digest, ConfigurationTerminalState.Confirmed));
        foreach (var entry in profile.Outbox ?? [])
            if (!entry.Published)
                repairs.Add(new(ConfigurationResidue.EvidenceOutbox, entry.EvidenceIntentId, ConfigurationTerminalState.Published));

        var record = new ConfigurationRecoveryRecord(request.RecoveryId, request.TenantKey, profile.EffectivePointer.Digest,
            repairs.AsReadOnly(), request.Reason, request.AuthoritySnapshot);
        var audit = new KernelAuditEvidence(
            $"{request.RecoveryId}:audit",
            request.ActorId,
            _clock.GetUtcNow(),
            JsonSerializer.SerializeToUtf8Bytes(new { capability = KernelProfile.ConfigurationRecovery, record }, AuditJson));
        var operation = new KernelOperationIdentity(request.RecoveryId, request.RecoveryId, Fingerprint(request));
        var committed = await KernelTransactionBoundary.ExecuteAsync([new(operation, record, audit)], port, cancellationToken)
            .ConfigureAwait(false);
        return committed.Committed
            ? new(record, committed.Value, null)
            : Refuse(committed.Refusal!.Code, "transaction-refused");
    }

    private static string Fingerprint(ConfigurationRecoveryRequest request) => Convert.ToHexStringLower(SHA256.HashData(
        Encoding.UTF8.GetBytes(string.Join('\n', request.TenantKey, request.ActorId, request.Reason, request.AuthoritySnapshot))));
}

namespace Harborline.Kernel.Core;

public static class KernelClockErrors
{
    public const string BackdateCapabilityRequired = "kernel.backdate-capability-required";
}

public interface IKernelBackdateCapability
{
    ValueTask<bool> CanBackdateAsync(
        string actorId,
        DateTimeOffset requestedEffectiveFrom,
        CancellationToken cancellationToken = default);
}

public sealed class KernelClockRefusalException(string code) : InvalidOperationException(code)
{
    public string Code { get; } = code;
}

/// <summary>The one authoritative clock supplied by a host composition root.</summary>
public sealed class KernelClock
{
    private readonly TimeProvider _provider;

    public KernelClock(TimeProvider provider) =>
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));

    public DateTimeOffset GetUtcNow() => _provider.GetUtcNow();

    public bool IsExpired(DateTimeOffset expiresAt) => GetUtcNow() >= expiresAt;

    public async ValueTask<DateTimeOffset> ResolveEffectiveFromAsync(
        string actorId,
        DateTimeOffset admittedAt,
        DateTimeOffset? requestedEffectiveFrom,
        IKernelBackdateCapability? backdateCapability = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(actorId);
        if (requestedEffectiveFrom is not { } requested) return admittedAt;
        if (requested >= admittedAt) return requested;
        if (backdateCapability is null
            || !await backdateCapability.CanBackdateAsync(actorId, requested, cancellationToken).ConfigureAwait(false))
            throw new KernelClockRefusalException(KernelClockErrors.BackdateCapabilityRequired);
        return requested;
    }
}

namespace Harborline.Kernel.Core;

public static class KernelClosureErrors
{
    public const string DependencyMissing = "kernel.closure.dependency-missing";
    public const string DependencyInactive = "kernel.closure.dependency-inactive";
    public const string DependencyBelowPin = "kernel.closure.dependency-below-pin";
    public const string Cycle = "kernel.closure.cycle";
    public const string VersionConflict = "kernel.closure.version-conflict";
    public const string VersionInvalid = "kernel.closure.version-invalid";
}

/// <summary>A declared dependency; <paramref name="MinimumVersion"/> is a minimum-inclusive SemVer floor.</summary>
public sealed record KernelPackageDependency(string Key, string MinimumVersion);

/// <summary>One package version as its own manifest declares it.</summary>
public sealed record KernelPackageManifest(string Key, string Version, IReadOnlyList<KernelPackageDependency> Dependencies);

public sealed class KernelClosureRefusalException(string code, IReadOnlyList<string> path)
    : InvalidOperationException($"{code}: {string.Join(" -> ", path)}")
{
    public string Code { get; } = code;
    /// <summary>The dependency path from the closure root to the package that could not be satisfied.</summary>
    public IReadOnlyList<string> Path { get; } = path;
}

/// <summary>A resolved package closure in install order: the platform package first, every dependency before its dependents.</summary>
public sealed class KernelPackageClosure
{
    public const string PlatformPackageKey = "harborline.platform";

    private KernelPackageClosure(IReadOnlyList<KernelPackageManifest> packages) => Packages = packages;

    public IReadOnlyList<KernelPackageManifest> Packages { get; }

    /// <summary>
    /// Walks <paramref name="roots"/> transitively over the manifests in <paramref name="packages"/>, with the platform
    /// package as the implicit first root. Each key resolves to exactly one version, which must be its
    /// <paramref name="active"/> version and meet every pin on it; a cycle is refused.
    /// </summary>
    public static KernelPackageClosure Resolve(
        IEnumerable<string> roots,
        IEnumerable<KernelPackageManifest> packages,
        IReadOnlyDictionary<string, string> active)
    {
        ArgumentNullException.ThrowIfNull(roots);
        ArgumentNullException.ThrowIfNull(packages);
        ArgumentNullException.ThrowIfNull(active);
        var byKey = new Dictionary<string, KernelPackageManifest>(StringComparer.Ordinal);
        foreach (var package in packages)
            if (!byKey.TryAdd(package.Key, package)) throw new KernelClosureRefusalException(KernelClosureErrors.VersionConflict, [package.Key]);

        var order = new List<KernelPackageManifest>();
        var resolved = new HashSet<string>(StringComparer.Ordinal);
        var path = new List<string>();
        Visit(PlatformPackageKey);
        foreach (var root in roots.Order(StringComparer.Ordinal)) Visit(root);
        return new KernelPackageClosure(order);

        void Visit(string key)
        {
            path.Add(key);
            if (path.IndexOf(key) != path.Count - 1) Refuse(KernelClosureErrors.Cycle);
            if (resolved.Add(key))
            {
                if (!byKey.TryGetValue(key, out var manifest)) Refuse(KernelClosureErrors.DependencyMissing);
                if (!active.TryGetValue(key, out var version)) Refuse(KernelClosureErrors.DependencyInactive);
                if (manifest!.Version != version) Refuse(KernelClosureErrors.VersionConflict);
                foreach (var dependency in manifest.Dependencies.OrderBy(dependency => dependency.Key, StringComparer.Ordinal))
                {
                    Visit(dependency.Key);
                    path.Add(dependency.Key);
                    if (Compare(Parse(active[dependency.Key]), Parse(dependency.MinimumVersion)) < 0)
                        Refuse(KernelClosureErrors.DependencyBelowPin);
                    path.RemoveAt(path.Count - 1);
                }
                order.Add(manifest);
            }
            path.RemoveAt(path.Count - 1);
        }

        void Refuse(string code) => throw new KernelClosureRefusalException(code, path.ToArray());

        SemanticVersion Parse(string value)
            => SemanticVersion.TryParse(value, out var parsed) ? parsed : throw new KernelClosureRefusalException(KernelClosureErrors.VersionInvalid, path.ToArray());
    }

    private sealed record SemanticVersion(string[] Core, string[] PreRelease)
    {
        public static bool TryParse(string value, out SemanticVersion parsed)
        {
            parsed = null!;
            var build = value.Split('+');
            var pieces = build[0].Split('-', 2);
            var core = pieces[0].Split('.');
            var preRelease = pieces.Length == 2 ? pieces[1].Split('.') : [];
            if (build.Length > 2 || (build.Length == 2 && !build[1].Split('.').All(Identifier))
                || core.Length != 3 || !core.All(part => Identifier(part) && Numeric(part) && NoLeadingZero(part))
                || !preRelease.All(part => Identifier(part) && (!Numeric(part) || NoLeadingZero(part))))
                return false;
            parsed = new(core, preRelease);
            return true;
        }

        private static bool Identifier(string part) => part.Length > 0 && part.All(c => char.IsAsciiLetterOrDigit(c) || c == '-');
        private static bool Numeric(string part) => part.All(char.IsAsciiDigit);
        private static bool NoLeadingZero(string part) => part.Length == 1 || part[0] != '0';
    }

    /// <summary>SemVer 2.0.0 section 11 precedence; build metadata is ignored.</summary>
    private static int Compare(SemanticVersion left, SemanticVersion right)
    {
        for (var index = 0; index < 3; index++)
        {
            var compared = CompareIdentifier(left.Core[index], right.Core[index]);
            if (compared != 0) return compared;
        }
        if (left.PreRelease.Length == 0 || right.PreRelease.Length == 0)
            return right.PreRelease.Length.CompareTo(left.PreRelease.Length);
        for (var index = 0; index < Math.Min(left.PreRelease.Length, right.PreRelease.Length); index++)
        {
            var compared = CompareIdentifier(left.PreRelease[index], right.PreRelease[index]);
            if (compared != 0) return compared;
        }
        return left.PreRelease.Length.CompareTo(right.PreRelease.Length);
    }

    private static int CompareIdentifier(string left, string right)
    {
        bool leftNumeric = left.All(char.IsAsciiDigit), rightNumeric = right.All(char.IsAsciiDigit);
        if (leftNumeric != rightNumeric) return leftNumeric ? -1 : 1;
        var compared = leftNumeric ? left.Length.CompareTo(right.Length) : 0;
        return compared != 0 ? compared : string.CompareOrdinal(left, right);
    }
}

namespace Harborline.Kernel.Core;

public static class KernelTransactionErrors
{
    public const string MultiCommandBatch = "kernel.multi-command-batch";
}

public sealed record KernelOperationIdentity(
    string CommandId,
    string IdempotencyKey,
    string Fingerprint)
{
    public KernelOperationIdentity Validate()
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(CommandId);
        ArgumentException.ThrowIfNullOrWhiteSpace(IdempotencyKey);
        ArgumentException.ThrowIfNullOrWhiteSpace(Fingerprint);
        return this;
    }
}

public sealed record KernelAuditEvidence(
    string AuditId,
    string ActorId,
    DateTimeOffset RecordedAt,
    ReadOnlyMemory<byte> Payload)
{
    public KernelAuditEvidence Validate()
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(AuditId);
        ArgumentException.ThrowIfNullOrWhiteSpace(ActorId);
        return this;
    }
}

public sealed record KernelCommand<TRecord>(
    KernelOperationIdentity Operation,
    TRecord Record,
    KernelAuditEvidence Audit);

public sealed record KernelTransactionRefusal(string Code, int ObservedCommandCount);

public sealed record KernelTransactionResult<TResult>(
    TResult? Value,
    KernelTransactionRefusal? Refusal)
{
    public bool Committed => Refusal is null;
}

/// <summary>
/// Host-backed transaction staged by the kernel boundary. Implementations must publish none of
/// the staged values before <see cref="CommitAsync"/> completes successfully.
/// </summary>
public interface IKernelTransaction<TRecord, TResult> : IAsyncDisposable
{
    ValueTask StageRecordAsync(TRecord record, CancellationToken cancellationToken = default);
    ValueTask StageAuditAsync(KernelAuditEvidence audit, CancellationToken cancellationToken = default);
    ValueTask<TResult> CommitAsync(CancellationToken cancellationToken = default);
    ValueTask RollbackAsync(CancellationToken cancellationToken = default);
}

public interface IKernelTransactionPort<TRecord, TResult>
{
    ValueTask<IKernelTransaction<TRecord, TResult>> BeginAsync(
        KernelOperationIdentity operation,
        CancellationToken cancellationToken = default);
}

/// <summary>
/// A transaction that is opened before its command can be prepared. The kernel still owns the
/// operation identity and the record/audit staging sequence once the producer returns a command.
/// </summary>
public interface IKernelPreparedTransaction<TRecord, TResult> : IAsyncDisposable
{
    ValueTask StageOperationAsync(KernelOperationIdentity operation, CancellationToken cancellationToken = default);
    ValueTask StageRecordAsync(TRecord record, CancellationToken cancellationToken = default);
    ValueTask StageAuditAsync(KernelAuditEvidence audit, CancellationToken cancellationToken = default);
    ValueTask<TResult> CommitAsync(CancellationToken cancellationToken = default);
    ValueTask RollbackAsync(CancellationToken cancellationToken = default);
}

public interface IKernelPreparedTransactionPort<TRecord, TResult>
{
    ValueTask<IKernelPreparedTransaction<TRecord, TResult>> BeginAsync(CancellationToken cancellationToken = default);
}

/// <summary>Owns one command's record, operation identity and audit commit or rollback.</summary>
public static class KernelTransactionBoundary
{
    /// <summary>
    /// Opens the host transaction before preparing its one command, then stages that command's
    /// operation, record, and audit before committing. The producer is never called after commit.
    /// </summary>
    public static async ValueTask<KernelTransactionResult<TResult>> ExecutePreparedAsync<TRecord, TResult>(
        Func<CancellationToken, ValueTask<KernelCommand<TRecord>>> prepare,
        IKernelPreparedTransactionPort<TRecord, TResult> port,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(prepare);
        ArgumentNullException.ThrowIfNull(port);

        await using var transaction = await port.BeginAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            var command = await prepare(cancellationToken).ConfigureAwait(false);
            ArgumentNullException.ThrowIfNull(command);
            command.Operation.Validate();
            command.Audit.Validate();
            await transaction.StageOperationAsync(command.Operation, cancellationToken).ConfigureAwait(false);
            await transaction.StageRecordAsync(command.Record, cancellationToken).ConfigureAwait(false);
            await transaction.StageAuditAsync(command.Audit, cancellationToken).ConfigureAwait(false);
            var value = await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return new(value, null);
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }

    public static async ValueTask<KernelTransactionResult<TResult>> ExecuteAsync<TRecord, TResult>(
        IEnumerable<KernelCommand<TRecord>> commands,
        IKernelTransactionPort<TRecord, TResult> port,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(commands);
        ArgumentNullException.ThrowIfNull(port);

        IReadOnlyList<KernelCommand<TRecord>> materialized = commands as IReadOnlyList<KernelCommand<TRecord>> ?? commands.ToArray();
        if (materialized.Count != 1)
            return new(default, new(KernelTransactionErrors.MultiCommandBatch, materialized.Count));

        var command = materialized[0];
        ArgumentNullException.ThrowIfNull(command);
        command.Operation.Validate();
        command.Audit.Validate();

        await using var transaction = await port.BeginAsync(command.Operation, cancellationToken)
            .ConfigureAwait(false);
        try
        {
            await transaction.StageRecordAsync(command.Record, cancellationToken).ConfigureAwait(false);
            await transaction.StageAuditAsync(command.Audit, cancellationToken).ConfigureAwait(false);
            var value = await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return new(value, null);
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }
}

using System.Text.Json;

